  function assetModal(){openOverlay(`<div class="backdrop modal-backdrop" data-close-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="asset-modal-title"><div class="modal-head"><h2 id="asset-modal-title">添加演示组件</h2><span class="spacer"></span><button class="btn icon-only" data-action="close" aria-label="关闭添加组件">${icon('close')}</button></div><form id="asset-form"><div class="modal-body"><p class="caption">只写入本次原型内存，刷新后恢复。不要填写真实主机或私密资产。</p><label class="field mt">显示名称<input class="input" name="name" required maxlength="60" placeholder="例如：示例推理组件"></label><label class="field">生态<select class="select" name="ecosystem"><option>PyPI</option></select></label><label class="field">包名<input class="input" name="package" required pattern="[A-Za-z0-9._]+(?:-[A-Za-z0-9._]+)*" placeholder="例如：vllm"></label><label class="field">精确安装版本<input class="input" name="version" required placeholder="例如：0.8.2，不能只填写2.6"></label><div id="asset-error" class="error-text" aria-live="polite"></div></div><div class="modal-foot">${btn('取消','close')}<button class="btn primary" type="submit">确认登记示例</button></div></form></section></div>`, '#asset-form input');}
